from typing import Iterable, List, Mapping, Tuple, Set
from src.stockflow.on_hand_by_location import on_hand_by_location
from src.stockflow.normalize_sku import normalize_sku
from src.stockflow.parse_location import parse_location


def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    raw_system_stock = on_hand_by_location(lines, case_sizes)
    system_stock = {}
    for (sku, loc_data), qty in raw_system_stock.items():
        if isinstance(loc_data, tuple):
            z, a, s, l = loc_data
            loc = f"{z}-{a:02d}-{s:02d}-{l}"
        else:
            loc = str(loc_data)
        system_stock[(sku, loc)] = qty

    normalized_counts = {}
    visited_locations: Set[str] = set()
    for (raw_sku, raw_loc), qty in counts.items():
        if qty < 0:
            raise ValueError("Counted quantity cannot be negative")
        sku = normalize_sku(raw_sku)
        z, a, s, l = parse_location(raw_loc)
        loc = f"{z}-{a:02d}-{s:02d}-{l}"
        key = (sku, loc)
        normalized_counts[key] = normalized_counts.get(key, 0) + qty
        visited_locations.add(loc)

    relevant_keys = set(normalized_counts.keys())
    for (sku, loc) in system_stock.keys():
        if loc in visited_locations:
            relevant_keys.add((sku, loc))

    variances = []
    for key in relevant_keys:
        sku, loc = key
        variance = normalized_counts.get(key, 0) - system_stock.get(key, 0)
        if variance != 0:
            variances.append((sku, loc, variance))

    variances.sort(key=lambda x: (x[1], x[0]))
    return variances
"}}}
